mlops-validate-rows.solution:
import re
from collections import Counter

def validate(rows, expectations):
    counts = {}
    for e in expectations:
        if e["type"] == "unique":
            c = e["column"]
            counts[c] = Counter(r.get(c) for r in rows if r.get(c) is not None)
    out = []
    for i, r in enumerate(rows):
        for e in expectations:
            c, t = e["column"], e["type"]
            v = r.get(c)
            bad = False
            if t == "not_null":
                bad = v is None
            elif v is None:
                bad = False
            elif t == "between":
                bad = not (e["min"] <= v <= e["max"])
            elif t == "in_set":
                bad = v not in e["values"]
            elif t == "regex":
                bad = re.fullmatch(e["pattern"], str(v)) is None
            elif t == "unique":
                bad = counts[c][v] > 1
            if bad:
                out.append([i, c, t])
    return out

