def pickChampion(runs, metric, mode):
    best, best_key = None, None
    for r in runs:
        if r.get("status") != "FINISHED" or metric not in r.get("metrics", {}):
            continue
        v = r["metrics"][metric]
        key = (-v if mode == "max" else v, r["metrics"].get("latency_ms", float("inf")), r["start_time"], r["run_id"])
        if best_key is None or key < best_key:
            best, best_key = r["run_id"], key
    return best

mlops-dag-order.solution:
import heapq

def taskOrder(tasks, deps):
    indeg = {t: 0 for t in tasks}
    adj = {t: set() for t in tasks}
    for u, v in deps:
        if v not in adj[u]:
            adj[u].add(v)
            indeg[v] += 1
    heap = [t for t in tasks if indeg[t] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        t = heapq.heappop(heap)
        order.append(t)
        for v in adj[t]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    return order if len(order) == len(tasks) else []

