mlops-psi.solution:
import math

def psi(expected, actual, bins):
    lo, hi = min(expected), max(expected)
    def frac(xs):
        c = [0] * bins
        for x in xs:
            k = math.floor((x - lo) / (hi - lo) * bins)
            c[min(bins - 1, max(0, k))] += 1
        return [max(v / len(xs), 1e-4) for v in c]
    e, a = frac(expected), frac(actual)
    return sum((ai - ei) * math.log(ai / ei) for ai, ei in zip(a, e))

mlops-ks-statistic.solution:
def ksStatistic(a, b):
    a, b = sorted(a), sorted(b)
    n, m = len(a), len(b)
    i = j = 0
    d = 0.0
    while i < n or j < m:
        if j >= m or (i < n and a[i] <= b[j]):
            x = a[i]
        else:
            x = b[j]
        while i < n and a[i] == x:
            i += 1
        while j < m and b[j] == x:
            j += 1
        d = max(d, abs(i / n - j / m))
    return d

